45	export interface ClaudeHarnessOptions {
46	  /** User-installed native executable; never installed, downloaded, or substituted by this adapter. */
47	  binary?: string;
48	  env?: NodeJS.ProcessEnv;
49	  platform?: NodeJS.Platform;
50	  preflightTimeoutMs?: number;
51	  maxOutputBytes?: number;
52	  /** Deterministic process transport injection; no provider call is needed for unit tests. */
53	  runner?: ClaudeCliRunner;
54	}
55	export interface ClaudeHarnessPreflight extends HarnessPreflight {
56	  authMethod: 'claude.ai' | null;
57	  supportedPolicies: ClaudePolicy[];
58	}
59	function failureState(error: unknown): Exclude<HarnessReadinessState, 'ready'> {
60	  const failure = error;
61	  if (!(failure instanceof ClaudeHarnessError)) return 'unknown';
62	  switch (failure.code) {
63	    case 'HARNESS_NOT_INSTALLED':
64	      return 'cli-missing';
65	    case 'HARNESS_CLI_INCOMPATIBLE':
66	    case 'HARNESS_UNSUPPORTED_POLICY':
67	      return 'cli-incompatible';
68	    case 'HARNESS_NOT_AUTHENTICATED':
69	      return 'auth';
70	    case 'HARNESS_QUOTA_EXHAUSTED':
71	      return 'quota';
72	    case 'HARNESS_TRANSPORT_FAILED':
73	      return 'transport';
74	    default:
75	      return 'unknown';
76	  }
77	}
78	/** Fresh names tried before a run of name collisions fails the check. */
79	const PROBE_DIRECTORY_ATTEMPTS = 4;
80	/**
81	 * A fresh, exclusively created, empty directory for the version, help and auth checks. Not
82	 * `fs.mkdtemp`: on Windows it hands its prefix to the OS without the long-path namespace and fails
83	 * with ENAMETOOLONG from 248 characters (247 still works), while `mkdir` and starting the CLI there
84	 * still work up to the 258-character working-directory limit (#102,
85	 * docs/qa/2026-10-19-wp-f5-launch-diagnosis.md). A name that already exists is never reused or
86	 * removed; a few fresh names are tried instead.
87	 */
88	async function probeDirectory(): Promise<string> {
89	  for (let attempt = 1; ; attempt += 1) {
90	    const directory = join(tmpdir(), `gg-claude-probe-${randomBytes(4).toString('hex')}`);
91	    try {
92	      await mkdir(directory, { mode: 0o700 });
93	      return directory;
94	    } catch (error) {
95	      if (
96	        (error as NodeJS.ErrnoException).code !== 'EEXIST' ||
97	        attempt === PROBE_DIRECTORY_ATTEMPTS
98	      )
99	        throw error;
100	    }
101	  }
102	}
103	/** Windows starts no process in a working directory longer than this (#102, #364). */
104	const WINDOWS_WORKING_DIRECTORY_LIMIT = 258;
105	/**
106	 * A refused start, worded from what the runner established (#364). A spawn `ENOENT` alone does not
107	 * say whether the executable or the working directory failed, so only an established absence is
108	 * reported as a missing CLI, and only the turn's own working directory is configuration; the
109	 * temporary check folder is not. Otherwise the cause stays unknown: the message names both
110	 * operands, or the Windows limit as a fact about the path's length. Messages are fixed text.
111	 */
112	function startFailure(
113	  code: NonNullable<ClaudeProcessResult['spawnCode']>,
114	  refusal: ClaudeStartRefusal | undefined,
115	  cwd: string,
116	  probe: boolean,
117	): ClaudeHarnessError {
118	  if (refusal === 'executable-missing')
119	    return new ClaudeHarnessError(
120	      'HARNESS_NOT_INSTALLED',
121	      probe
122	        ? 'Claude CLI was not found at the configured path.'
123	        : 'The Claude executable was not found at its configured path; install the Claude CLI or correct its path',
124	    );
125	  if (refusal) {
126	    const state = refusal === 'working-directory-missing' ? 'does not exist' : 'is not a folder';
127	    return probe
128	      ? new ClaudeHarnessError(
129	          'HARNESS_TURN_FAILED',
130	          `Claude CLI could not be started because its temporary check folder ${state}.`,
131	        )
132	      : new ClaudeHarnessError(
133	          'HARNESS_INVALID_CONFIGURATION',
134	          `Claude could not be started because the working directory ${state}; check the working directory setting`,
135	        );
136	  }
137	  const limit = WINDOWS_WORKING_DIRECTORY_LIMIT;
138	  const long = resolve(cwd).length > limit;
139	  if (probe)
140	    return new ClaudeHarnessError(
141	      'HARNESS_TURN_FAILED',
142	      long
143	        ? `Claude CLI could not be started (${code}) from its temporary check folder, whose path (from TEMP or TMP) is longer than the ${limit} characters Windows allows for a working directory.`
144	        : `Claude CLI could not be started (${code}).`,
145	    );
146	  return new ClaudeHarnessError(
147	    'HARNESS_TURN_FAILED',
148	    long
149	      ? `Claude could not be started (${code}); the working directory path is longer than the ${limit} characters Windows allows`
150	      : `Claude could not be started (${code}); check the Claude executable's path and permissions and the working directory`,
151	  );
152	}
153	/**
154	 * Turns and no-turn probes share the failure order. A probe's messages are single detail
155	 * sentences about the check (preflight adds the one next step).
156	 */
157	function checkOutcome(
158	  result: ClaudeProcessResult,
159	  signal: AbortSignal,
160	  cwd: string,
161	  probe = false,
162	): void {
163	  if (result.terminationUnconfirmed)
164	    throw new ClaudeHarnessError(
165	      'HARNESS_TERMINATION_UNCONFIRMED',
166	      probe
167	        ? 'Claude CLI check process did not confirm that it stopped.'
168	        : 'Claude process termination was not confirmed; stop the installed CLI before retrying',
169	    );
170	  if (signal.aborted || result.aborted) throw abortError();
171	  if (result.spawnCode) throw startFailure(result.spawnCode, result.startRefusal, cwd, probe);
172	  if (result.timedOut)
173	    throw new ClaudeHarnessError(
174	      'HARNESS_TIMEOUT',
175	      probe ? 'Claude CLI did not answer before the check deadline.' : 'Claude process timed out',
176	      true,
177	    );
178	  if (result.overflow)
179	    throw new ClaudeHarnessError(
180	      'HARNESS_OUTPUT_LIMIT',
181	      probe
182	        ? 'Claude CLI printed more output than the check accepts.'
183	        : 'Claude process output exceeded the configured limit',
184	    );
185	  if (result.callbackError) throw result.callbackError;
186	  if (probe && result.exitCode !== 0 && result.failureState && result.failureState !== 'unknown') {
187	    const codes: Partial<
188	      Record<HarnessReadinessState, ConstructorParameters<typeof ClaudeHarnessError>[0]>
189	    > = {
190	      auth: 'HARNESS_NOT_AUTHENTICATED',
191	      quota: 'HARNESS_QUOTA_EXHAUSTED',
192	      transport: 'HARNESS_TRANSPORT_FAILED',
193	      'cli-incompatible': 'HARNESS_CLI_INCOMPATIBLE',
194	    };
195	    throw new ClaudeHarnessError(
196	      codes[result.failureState] ?? 'HARNESS_TURN_FAILED',
197	      readinessDetail('claude', result.failureState),
198	      result.failureState === 'transport',
199	    );
200	  }
201	  if (probe && result.outputFailed)
202	    throw new ClaudeHarnessError(
203	      'HARNESS_TURN_FAILED',
204	      'Claude CLI check output could not be read.',
205	    );
206	  if (probe && (result.stdinFailed || result.exitCode !== 0))
207	    throw new ClaudeHarnessError(
208	      'HARNESS_TURN_FAILED',
209	      result.exitCode === null
210	        ? 'Claude CLI check stopped without an exit code.'
211	        : `Claude CLI check exited with code ${result.exitCode}.`,
212	    );
213	  if (result.stdinFailed || result.outputFailed || result.exitCode !== 0)
214	    throw new ClaudeHarnessError('HARNESS_TURN_FAILED', 'Claude turn failed');
215	}
216	/** Structural current HarnessPort implementation; additive HarnessId integration follows the issue 98 cutover. */
217	export class ClaudeHarness implements HarnessPort {
218	  readonly id = 'claude' as const;
219	  private readonly binary: string;
220	  private readonly runner: ClaudeCliRunner;
221	  private readonly platform: NodeJS.Platform;
222	  private readonly environment: NodeJS.ProcessEnv;
223	  constructor(private readonly options: ClaudeHarnessOptions = {}) {
224	    this.binary =
225	      options.binary ??
226	      join(
227	        options.env?.USERPROFILE ?? process.env.USERPROFILE ?? homedir(),
228	        '.local',
229	        'bin',
230	        'claude.exe',
231	      );
232	    this.runner = options.runner ?? runClaudeProcess;
233	    this.platform = options.platform ?? process.platform;
234	    this.environment = subscriptionEnvironment(options.env ?? process.env);
235	    for (const value of [options.preflightTimeoutMs, options.maxOutputBytes])
236	      if (value !== undefined && (!Number.isSafeInteger(value) || value <= 0))
237	        throw new ClaudeHarnessError(
238	          'HARNESS_INVALID_CONFIGURATION',
239	          'Claude process bounds must be positive integers',
240	        );
241	  }
242	  private supportedPolicies(): ClaudePolicy[] {
243	    return (['read-only', 'danger-full-access'] as const).map((sandbox) =>
244	      claudePolicy({ sandbox, approval: 'never' }, undefined, this.platform),
245	    );
246	  }
247	  private async inspect(signal: AbortSignal): Promise<{
248	    facts: ClaudeHarnessPreflight;
249	    failures: unknown[];
250	  }> {
251	    const facts: ClaudeHarnessPreflight = {
252	      state: 'unknown',
253	      ok: false,
254	      problems: [],
255	      authMethod: null,
256	      models: claudeModelCapabilities(),
257	      supportedPolicies: [],
258	    };
259	    const failures: unknown[] = [];
260	    // Unsupported platforms cannot execute this native Windows adapter.
261	    facts.supportedPolicies = this.supportedPolicies();
262	    const cwd = await probeDirectory();
263	    const run = async (args: string[], authStatus = false): Promise<string> => {
264	      if (signal.aborted) throw abortError();
265	      const result = await this.runner({
266	        binary: this.binary,
267	        args,
268	        cwd,
269	        env: this.environment,
270	        signal,
271	        timeoutMs: this.options.preflightTimeoutMs ?? 15000,
272	        maxOutputBytes: 128 * 1024,
273	        classifyDiagnostics: true,
274	      });
275	      // Auth status can confirm sign-out in JSON or text, even on exit 0. Interpret it only here;
276	      // timeout/start/termination failures remain authoritative and turn output is never inferred.
277	      let auth: unknown;
278	      if (authStatus) {
279	        try {
280	          auth = JSON.parse(result.stdout);
281	        } catch {
282	          /* No structured status. */
283	        }
284	      }
285	      let signOutDetail: string | undefined;
286	      if (
287	        typeof auth === 'object' &&
288	        auth !== null &&
289	        (('loggedIn' in auth && auth.loggedIn === false) ||
290	          ('authMethod' in auth &&
291	            typeof auth.authMethod === 'string' &&
292	            auth.authMethod !== '' &&
293	            auth.authMethod !== 'claude.ai'))
294	      ) {
295	        signOutDetail =
296	          'loggedIn' in auth && auth.loggedIn === false
297	            ? 'Claude is not signed in.'
298	            : 'Claude is not signed in with a Claude.ai account.';
299	      }
300	      if (
301	        authStatus &&
