351	      failures.push(error);
352	    }
353	    // Login is a separate fact, even when the CLI version or policy flags are unsupported.
354	    try {
355	      const auth = await run([...SUPPRESSION_ARGS, 'auth', 'status', '--json'], true);
356	      facts.authMethod = authCategory(auth);
357	      if (facts.authMethod === null)
358	        throw new ClaudeHarnessError('HARNESS_TURN_FAILED', readinessDetail('claude', 'unknown'));
359	      facts.authenticated = true;
360	    } catch (error) {
361	      if (failureState(error) === 'auth') facts.authenticated = false;
362	      failures.push(error);
363	    }
364	    try {
365	      await rm(cwd, { recursive: true, force: true });
366	    } catch {
