402	      };
403	    }
404	  }
405	  start(request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
406	    return this.turn(request, signal);
407	  }
408	  resume(sessionId: string, request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
409	    return this.turn(request, signal, sessionId);
410	  }
411	  private turn(
412	    request: HarnessStartRequest,
413	    signal: AbortSignal,
414	    resumeId?: string,
415	  ): HarnessSession {
416	    const controller = new AbortController();
417	    const abort = () => controller.abort();
418	    if (signal.aborted) abort();
419	    else signal.addEventListener('abort', abort, { once: true });
420	    const queue = new EventQueue<HarnessEvent>();
