424	      resolveId = resolve;
425	      rejectId = reject;
426	    });
427	    sessionId.catch(() => undefined);
428	    const pump = async (): Promise<HarnessResult> => {
429	      let detectedVersion: string | undefined;
430	      let delivery: PromptSubmission = 'definitely-not-submitted';
431	      let accepted = false;
432	      let initialized = false;
433	      try {
434	        if (controller.signal.aborted) throw abortError();
435	        if (resumeId !== undefined && !validClaudeSessionId(resumeId))
436	          throw new ClaudeHarnessError(
437	            'HARNESS_INVALID_CONFIGURATION',
438	            'Claude resume requires a valid native session id',
439	          );
440	        const policy = claudePolicy(request.options, request.capabilities, this.platform);
441	        const settings = resolvedClaudeSettings(request);
442	        const inspection = await this.inspect(controller.signal);
443	        if (!inspection.facts.ok) throw inspection.failures[0];
444	        detectedVersion = inspection.facts.version;
445	        const accumulator = new ClaudeAccumulator({
446	          policy,
447	          model: settings.model,
448	          effort: settings.effort,
449	          mode: resumeId ? 'resumed' : 'fresh',
450	          ...(resumeId ? { resumeId } : {}),
451	          ...(request.turn.outputSchema ? { schema: request.turn.outputSchema } : {}),
452	        });
453	        const parser = new JsonLines();
454	        let completionEvents: HarnessEvent[] = [];
455	        const accept = (record: Record<string, unknown>): void => {
456	          // Native missing-session refusals can precede init (CLI 2.1.304). They are not
457	          // turn output. Await the fixed stderr refusal; never retain the provider error body.
458	          if (
459	            !initialized &&
460	            !accepted &&
461	            record.type === 'result' &&
462	            record.is_error === true &&
463	            record.num_turns === 0
464	          )
465	            return;
466	          const events = accumulator.push(record);
467	          if (events.some((event) => event.type === 'session')) initialized = true;
468	          if (events.some((event) => event.type === 'submitted')) accepted = true;
469	          if (record.type === 'result') {
470	            // A validated result proves consumption even while the CLI is still alive.
471	            // Persist that evidence now; usage/completion remain gated by process outcome.
472	            completionEvents = [];
473	            for (const event of events) {
474	              if (event.type === 'submitted') queue.push(event);
475	              else completionEvents.push(event);
476	            }
477	            return;
478	          }
479	          for (const event of events) {
480	            if (event.type === 'session') resolveId(event.sessionId);
481	            queue.push(event);
482	          }
483	        };
484	        const args = [
485	          ...policyArgs(policy),
486	          '--model',
487	          settings.model,
488	          '--effort',
489	          settings.effort,
490	          '--output-format',
491	          'stream-json',
492	          '--verbose',
493	          ...(resumeId ? ['--resume', resumeId] : []),
494	          ...(request.turn.outputSchema
495	            ? ['--json-schema', JSON.stringify(request.turn.outputSchema)]
496	            : []),
497	          '--input-format',
498	          'text',
499	          '--print',
500	        ];
501	        delivery = 'delivery-uncertain';
502	        const result = await this.runner(
503	          {
504	            binary: this.binary,
505	            args,
506	            cwd: request.workingDirectory,
507	            env: this.environment,
508	            stdin: request.turn.prompt,
509	            signal: controller.signal,
510	            timeoutMs: null,
511	            maxOutputBytes: this.options.maxOutputBytes ?? 4 * 1024 * 1024,
512	          },
513	          (chunk) => {
514	            for (const record of parser.push(chunk)) accept(record);
515	          },
516	        );
517	        if (result.spawnCode) delivery = 'definitely-not-submitted';
518	        // Refusal diagnostics must never conceal an unconfirmed process or a transport cutoff.
519	        if (
520	          result.terminationUnconfirmed ||
521	          result.aborted ||
522	          result.timedOut ||
523	          result.overflow ||
524	          result.outputFailed ||
525	          result.callbackError
526	        )
527	          checkOutcome(result, controller.signal, request.workingDirectory);
528	        if (!accepted && result.turnRejection) {
529	          delivery =
530	            result.turnRejection === 'session-missing'
531	              ? 'session-missing'
532	              : 'definitely-not-submitted';
533	          if (result.turnRejection === 'session-missing')
534	            throw new ClaudeHarnessError(
535	              'HARNESS_SESSION_MISSING',
536	              'The recorded Claude conversation was not found',
537	            );
538	          if (result.turnRejection === 'auth')
539	            throw new ClaudeHarnessError(
540	              'HARNESS_NOT_AUTHENTICATED',
541	              'Claude requires authentication before submitting this turn',
542	            );
543	        }
544	        checkOutcome(result, controller.signal, request.workingDirectory);
545	        for (const record of parser.finish()) accept(record);
546	        const completed = accumulator.finish();
547	        for (const event of completionEvents) queue.push(event);
548	        return completed;
549	      } catch (error) {
550	        const failure =
551	          error instanceof ClaudeHarnessError && error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
552	            ? error
553	            : controller.signal.aborted
554	              ? abortError()
555	              : error instanceof ClaudeHarnessError
556	                ? error.code === 'HARNESS_PROTOCOL_ERROR' && detectedVersion !== undefined
557	                  ? new ClaudeHarnessError(
558	                      error.code,
559	                      `Claude CLI ${detectedVersion}: required capability stream-json protocol verification failed: ${error.message}`,
560	                      error.retriable,
561	                    )
562	                  : error.code === 'HARNESS_UNSUPPORTED_POLICY' && detectedVersion !== undefined
563	                    ? new ClaudeHarnessError(
564	                        error.code,
565	                        `Claude CLI ${detectedVersion}: required capability effective launch policy verification failed: ${error.message}`,
566	                        error.retriable,
567	                      )
568	                    : error
569	                : new ClaudeHarnessError('HARNESS_TURN_FAILED', 'Claude turn failed');
570	        rejectId(failure);
571	        if (failure instanceof ClaudeHarnessError)
572	          queue.push({
573	            type: 'error',
574	            code: failure.code,
575	            message: failure.message,
576	            retriable: failure.retriable,
577	            submission: delivery,
578	          });
579	        throw failure;
580	      } finally {
581	        closed = true;
582	        signal.removeEventListener('abort', abort);
583	        queue.close();
584	      }
585	    };
586	    const result = pump();
587	    result.catch(() => undefined);
588	    let cancellation: Promise<void> | undefined;
589	    return {
590	      sessionId,
591	      events: queue,
592	      result,
593	      cancel: () => {
594	        if (closed)
595	          return result.then(
596	            () => undefined,
597	            (error: unknown) => {
598	              if (
599	                error instanceof ClaudeHarnessError &&
600	                error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
601	              )
602	                throw error;
603	            },
604	          );
605	        cancellation ??= (async () => {
606	          controller.abort();
607	          await result.catch((error: unknown) => {
608	            if (
609	              error instanceof ClaudeHarnessError &&
610	              error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
611	            )
612	              throw error;
613	          });
614	        })();
615	        return cancellation;
616	      },
617	    };
618	  }
619	}
