1	import { spawn } from 'node:child_process';
2	import { stat } from 'node:fs/promises';
3	import { isAbsolute, normalize, resolve as resolvePath } from 'node:path';
4	import { killTree } from '../process/index.js';
5	import { ClaudeHarnessError } from './errors.js';
6	import { cliFailureState } from '@graphgoblin/domain';
7	import type { HarnessReadinessState } from '@graphgoblin/contracts';
8	export interface ClaudeProcessRequest {
9	  binary: string;
10	  args: readonly string[];
11	  cwd: string;
12	  env: NodeJS.ProcessEnv;
13	  stdin?: string;
14	  signal: AbortSignal;
15	  timeoutMs: number | null;
16	  maxOutputBytes: number;
17	  /** Readiness diagnostic inference is permitted only for no-turn prerequisite probes. */
18	  classifyDiagnostics?: true;
19	}
20	export interface ClaudeProcessResult {
21	  exitCode: number | null;
22	  stdout: string;
23	  timedOut: boolean;
24	  aborted: boolean;
25	  overflow: boolean;
26	  /** Set only for an actual spawn refusal: no process was created, so nothing was submitted. */
27	  spawnCode?: 'ENOENT' | 'EACCES' | 'UNKNOWN';
28	  /**
29	   * The cause of a spawn refusal, when the read-only observation made after it established one.
30	   * Absent when the cause is unknown, including when an observation could not be read.
31	   */
32	  startRefusal?: ClaudeStartRefusal;
33	  /** Kill deadline elapsed without the child's close event; never treat this as successful cancellation. */
34	  terminationUnconfirmed?: true;
35	  stdinFailed?: boolean;
36	  /** A started process's stdout or stderr pipe failed, so its output is incomplete. */
37	  outputFailed?: true;
38	  callbackError?: ClaudeHarnessError;
39	  /** Fixed classification only; stdout/stderr diagnostic bodies are never retained here. */
40	  failureState?: HarnessReadinessState;
41	  /** Fixed pre-turn refusal inferred only from bounded CLI stderr, never model stdout. */
42	  turnRejection?: 'arguments' | 'auth' | 'session-missing';
43	  /** Positive sign-out text in bounded no-turn stderr; never a retained diagnostic body. */
44	  notLoggedIn?: true;
45	}
46	export type ClaudeCliRunner = (
47	  request: ClaudeProcessRequest,
48	  onStdout?: (chunk: Buffer) => void,
49	) => Promise<ClaudeProcessResult>;
50	export type ClaudeStartRefusal =
51	  'executable-missing' | 'working-directory-missing' | 'working-directory-not-directory';
52	type PathState = 'missing' | 'directory' | 'other' | 'unknown';
53	async function pathState(path: string): Promise<PathState> {
54	  try {
55	    return (await stat(path)).isDirectory() ? 'directory' : 'other';
56	  } catch (error) {
57	    const code = (error as NodeJS.ErrnoException).code;
58	    // Only a definite absence counts; access, length or other read faults leave the cause unknown.
59	    return code === 'ENOENT' || code === 'ENOTDIR' ? 'missing' : 'unknown';
60	  }
61	}
62	/**
63	 * Read-only observation after a spawn refusal (#364). A spawn `ENOENT` does not say which operand
64	 * failed: Windows also reports a missing, non-folder or overlong working directory that way. An
65	 * executable counts as missing only for a fully qualified path whose every name Windows process
66	 * start tries (the path, then with `.com` and `.exe` appended) is absent or a folder; a bare name
67	 * or relative path is never resolved here. An existing folder is not proof that a process can
68	 * start in it, so it establishes nothing.
69	 */
70	async function observeStartRefusal(
71	  request: ClaudeProcessRequest,
72	  code: NonNullable<ClaudeProcessResult['spawnCode']>,
73	): Promise<ClaudeStartRefusal | undefined> {
74	  const binary = request.binary;
75	  if (code === 'ENOENT' && isAbsolute(binary) && resolvePath(binary) === normalize(binary)) {
76	    const names =
77	      process.platform === 'win32' ? [binary, `${binary}.com`, `${binary}.exe`] : [binary];
78	    const states = await Promise.all(names.map(pathState));
79	    if (states.every((state) => state === 'missing' || state === 'directory'))
80	      return 'executable-missing';
81	  }
82	  const directory = await pathState(request.cwd);
83	  if (directory === 'missing') return 'working-directory-missing';
84	  if (directory === 'other') return 'working-directory-not-directory';
85	  return undefined;
86	}
87	/** Own every child and its descendants, with no shell, bounded capture and fixed diagnostic codes. */
88	export const runClaudeProcess = (
89	  request: ClaudeProcessRequest,
90	  onStdout?: (chunk: Buffer) => void,
91	  /** Optional ephemeral observer; stderr is never retained in the result. */
92	  onStderr?: (chunk: Buffer) => void,
93	): Promise<ClaudeProcessResult> =>
94	  new Promise((resolve) => {
95	    const empty = { exitCode: null, stdout: '', timedOut: false, aborted: false, overflow: false };
96	    if (request.signal.aborted) {
97	      resolve({ ...empty, aborted: true });
98	      return;
99	    }
100	    const child = spawn(request.binary, [...request.args], {
101	      cwd: request.cwd,
102	      env: request.env,
103	      windowsHide: true,
104	      detached: process.platform !== 'win32',
105	      shell: false,
106	      stdio: ['pipe', 'pipe', 'pipe'],
107	    });
108	    let stdout = '',
109	      bytes = 0,
110	      settled = false,
111	      timedOut = false,
112	      overflow = false,
113	      stdinFailed = false,
114	      outputFailed = false;
115	    let callbackError: ClaudeHarnessError | undefined, spawnCode: ClaudeProcessResult['spawnCode'];
116	    let startRefusal: ClaudeStartRefusal | undefined;
117	    let killing: Promise<boolean> | undefined;
118	    let closed = false;
119	    let treeConfirmed = false;
120	    let closeCode: number | null = null;
121	    let killTimer: ReturnType<typeof setTimeout> | undefined;
122	    let diagnostic = '';
123	    let rejection: ClaudeProcessResult['turnRejection'];
124	    const finish = (exitCode: number | null, terminationUnconfirmed = false): void => {
125	      if (settled) return;
126	      settled = true;
127	      clearTimeout(timer);
128	      if (killTimer) clearTimeout(killTimer);
129	      request.signal.removeEventListener('abort', kill);
130	      resolve({
131	        exitCode,
132	        stdout,
133	        timedOut,
134	        aborted: request.signal.aborted,
135	        overflow,
136	        ...(terminationUnconfirmed ? { terminationUnconfirmed: true } : {}),
137	        ...(spawnCode ? { spawnCode } : {}),
138	        ...(startRefusal ? { startRefusal } : {}),
139	        ...(exitCode !== 0 && rejection ? { turnRejection: rejection } : {}),
140	        ...(stdinFailed ? { stdinFailed } : {}),
141	        ...(outputFailed ? { outputFailed: true } : {}),
142	        ...(callbackError ? { callbackError } : {}),
143	        ...(request.classifyDiagnostics && exitCode !== 0 && diagnostic
144	          ? { failureState: cliFailureState(diagnostic) }
145	          : {}),
146	        ...(request.classifyDiagnostics && /\bnot logged in\b/i.test(diagnostic)
147	          ? { notLoggedIn: true }
148	          : {}),
149	      });
150	    };
151	    const kill = (): void => {
152	      if (settled) return;
153	      clearTimeout(timer);
154	      // A refused start has no process to stop: report the refusal now, without its diagnosis.
155	      if (spawnCode) {
156	        finish(null);
157	        return;
158	      }
159	      if (killing) return;
160	      killTimer = setTimeout(() => finish(null, true), 5000);
161	      killing = killTree(child);
162	      void killing.then((confirmed) => {
163	        if (!confirmed) finish(null, true);
164	        else {
165	          treeConfirmed = true;
166	          if (closed) finish(closeCode);
167	        }
168	      });
169	    };
170	    const timer =
171	      request.timeoutMs === null
172	        ? undefined
173	        : setTimeout(() => {
174	            // A process that never started cannot have timed out.
175	            if (!spawnCode) timedOut = true;
176	            kill();
177	          }, request.timeoutMs);
178	    request.signal.addEventListener('abort', kill, { once: true });
179	    const collect = (chunk: Buffer, output: boolean): void => {
180	      if (settled || overflow || callbackError) return;
181	      bytes += chunk.byteLength;
182	      if (bytes > request.maxOutputBytes) {
183	        overflow = true;
184	        kill();
185	        return;
186	      }
187	      try {
188	        // Keep only stderr in this ephemeral window. Turn stdout can contain authored/model text.
189	        // The same bounded buffer supports turn refusals and probe-only sign-out inference;
190	        // only fixed classifications leave it. Probe stdout is inspected separately by the harness.
191	        if (!output) {
192	          diagnostic = (diagnostic + chunk.toString('utf8')).slice(-8192);
193	          if (/^(?:Error: )?No conversation found with session ID:/im.test(diagnostic))
194	            rejection = 'session-missing';
195	          else if (/^error: (?:unknown option|unexpected argument)/im.test(diagnostic))
196	            rejection = 'arguments';
197	          else if (
198	            /^(?:Error: )?(?:Not logged in|Invalid API key|Authentication required)\b/im.test(
199	              diagnostic,
200	            )
201	          )
202	            rejection = 'auth';
203	        }
204	        if (output) {
205	          stdout += chunk.toString('utf8');
206	          onStdout?.(chunk);
207	        } else onStderr?.(chunk);
208	      } catch (error) {
209	        callbackError =
210	          error instanceof ClaudeHarnessError
211	            ? error
212	            : new ClaudeHarnessError('HARNESS_PROTOCOL_ERROR', 'Claude stream parser failed');
213	        kill();
214	      }
215	    };
