217	    // Windows from a 260-character working directory, stdout and stderr fail with ENOTCONN); the
218	    // refusal itself arrives as the child's error event, so those secondary faults are ignored.
219	    const started = (): boolean => child.pid !== undefined;
220	    const outputFault = (): void => {
221	      if (!started()) return;
222	      outputFailed = true;
223	      kill();
224	    };
225	    child.stdout?.on('data', (chunk: Buffer) => collect(chunk, true));
226	    child.stderr?.on('data', (chunk: Buffer) => collect(chunk, false));
227	    child.stdout?.on('error', outputFault);
228	    child.stderr?.on('error', outputFault);
229	    child.on('error', (error: NodeJS.ErrnoException) => {
230	      // Only an actual spawn refusal proves that nothing started. A later error, such as a failed
231	      // kill, leaves the close and termination outcomes authoritative.
232	      if (settled || spawnCode || started()) return;
233	      const code =
234	        error.code === 'ENOENT' ? 'ENOENT' : error.code === 'EACCES' ? 'EACCES' : 'UNKNOWN';
235	      spawnCode = code;
236	      void observeStartRefusal(request, code).then((observed) => {
237	        startRefusal = observed;
238	        finish(null);
239	      });
240	    });
241	    child.on('close', (code) => {
242	      closed = true;
243	      closeCode = code;
244	      // After a refusal Node still closes the child; the refusal path settles the result.
245	      if (spawnCode) return;
246	      if (!killing || treeConfirmed) finish(code);
247	    });
248	    child.stdin?.on('error', () => {
249	      if (!started()) return;
250	      stdinFailed = true;
251	      kill();
252	    });
253	    child.stdin?.end(request.stdin ?? '');
254	  });
