  const binary = join(homedir(), '.local', 'bin', 'claude.exe');
  if (process.platform !== 'win32' || !existsSync(binary)) {
    context.skip('Native Windows Claude binary missing');
    return;
  }
  const home = await mkdtemp(join(tmpdir(), 'gg-claude-signed-out-'));
