      env: { ...process.env, USERPROFILE: home, HOME: home },
    }).preflight();
    expect(result).toMatchObject({ state: 'auth', ok: false, authenticated: false });
  } finally {
    await rm(home, { recursive: true, force: true });
  }
}, 60000);

